// Editorial source: every situation, response, distractor and repair is authored.
// Helpers package records; they do not invent sentences or inferred meanings.
export const W=(it,en,article,plural)=>({it,en,...article?{article}:{},...plural?{plural}:{}});
export const C=(context,translation,answer,options,explanation)=>({format:'choice',prompt:'Choose the wording that fits the stated situation.',context,translation,answer,options,explanation,hint:explanation,speak:context.replace('___',answer)});
export const T=(context,translation,answer,explanation,accepted=[])=>({format:'type',prompt:'Complete the gap with the taught wording requested in English.',context,translation,answer,accepted,strict:true,explanation,hint:explanation,speak:context.replace('___',answer)});
export const F=(key,label,body,it,en,questions)=>({key,label,body,examples:[{it,en}],questions});
export const S=(it,en,prompt,answer,options,explanation)=>({it,en,prompt,answer,options,explanation});
const request='Potere in the conditional: io potrei, tu potresti, lui/lei/Lei potrebbe, noi potremmo, voi potreste, loro potrebbero. Use Lei with an unfamiliar service worker. A specific request tells them what action would help.';
const past='Avere in the present: io ho, tu hai, lui/lei/Lei ha, noi abbiamo, voi avete, loro hanno. In these completed actions add the stated participle; the subject sets the auxiliary person.';
const L=(id,title,outcome,prerequisites,domains,words,facets,passage,portfolio,related=[])=>({id,title,outcome:'Practise how to '+outcome.replace(/^I can /,''),prerequisites,domains,words,facets,passage,portfolio,related});

export const a2Language=[
 L('v2-a2-service-appointment','Arrange a useful appointment','I can request a service appointment and confirm a workable day and time.',['v2-a2-conditional-request','v2-a2-formal-request','v2-a1-calendar-read'],['appointments','services','polite-register'],[W('spostare','to move/reschedule'),W('confermare','to confirm'),W('appuntamento','appointment','l’','appuntamenti'),W('disponibile','available'),W('martedì','Tuesday'),W('giovedì','Thursday'),W('alle quindici','at three in the afternoon')],[
  F('request','Make a specific polite request',request+' Potrebbe spostare…? requests rescheduling; vorrei fissare… states the desired appointment. Spostare and fissare are infinitives after the request frame.','Potrebbe spostare l’appuntamento a giovedì?','Could you move the appointment to Thursday?',[
   C('Parli con l’addetta: «___ spostare l’appuntamento?»','Address one receptionist politely.','Potrebbe',['Potrebbe','Potresti','Potreste'],'Lei takes potrebbe; potresti addresses tu and potreste a group.'),
   T('___ confermare l’orario, per favore?','Could you confirm the time, please? Address one clerk with Lei.','Potrebbe','Use the Lei conditional before the infinitive confermare.'),
   C('«___ fissare un appuntamento per giovedì.»','State what you would like to arrange.','Vorrei',['Vorrei','Volevo dire','Sono stato'],'Vorrei + infinitive states the desired action.'),
   T('Vorrei ___ l’appuntamento a martedì.','I would like to move the appointment to Tuesday. Use spostare.','spostare','After vorrei keep the infinitive spostare.'),
   C('La visita è venerdì, ma venerdì lavoro. «___»','Ask to change the existing appointment.','Potrebbe spostare la visita?',['Potrebbe spostare la visita?','Potrebbe ripetere il cognome?','Vorrei pagare la visita.'],'The stated problem concerns the appointment day, so ask to move it.'),
   T('___ fissare una visita per domani.','I would like to arrange a visit for tomorrow. Use volere in the io conditional.','Vorrei','Vorrei names the desired action without changing the infinitive.'),
   T('___ ripetere l’indirizzo?','Could you repeat the address? Use Lei and the conditional of potere.','Potrebbe','Formal Lei uses third-person singular potrebbe.')]),
  F('confirm','Confirm the final arrangement','An accepted alternative replaces the earlier proposal. Confermo… explicitly confirms; a question about availability does not yet confirm a booking. Confermare present: io confermo, tu confermi, lui/lei/Lei conferma, noi confermiamo, voi confermate, loro confermano.','Giovedì alle quindici va bene. Confermo l’appuntamento.','Thursday at three is all right. I confirm the appointment.',[
   C('«Martedì non sono disponibile. Giovedì?» «___»','Accept Thursday.','Giovedì va bene.',['Giovedì va bene.','Martedì va bene.','Non so che giorno.'],'Accept the newly offered Thursday, not the rejected Tuesday.'),
   T('___ l’appuntamento di giovedì.','I confirm the Thursday appointment. Use confermare in the io present.','Confermo','Confermo states the speaker’s confirmation.'),
   C('«Alle quindici?» «___»','Confirm that proposed time.','Sì, alle quindici.',['Sì, alle quindici.','No, giovedì.','Quale cognome?'],'Keep the requested time rather than answering a different detail.'),
   T('Noi ___ l’orario di domani.','We confirm tomorrow’s time. Use confermare in the noi present.','confermiamo','The plural subject noi takes confermiamo.'),
   C('«Giovedì alle quindici, conferma?» «___»','You accept both final details.','Sì, giovedì alle quindici.',['Sì, giovedì alle quindici.','Sì, martedì alle quindici.','Sì, giovedì alle dieci.'],'Confirmation preserves both day and time.'),
   T('La cliente ___ l’appuntamento.','The customer confirms the appointment. Use the present of confermare.','conferma','La cliente is third-person singular.'),
   T('Voi ___ la visita di venerdì.','You all confirm Friday’s visit. Use the present of confermare.','confermate','Voi takes confermate, distinct from noi confermiamo.')])],
  ['read','An appointment changed','Cliente: «Martedì lavoro. Potrebbe spostare la visita?»\nAddetta: «Giovedì alle quindici?»\nCliente: «Va bene. Confermo giovedì alle quindici.»','Customer: “I work on Tuesday. Could you move the visit?”\nReceptionist: “Thursday at three?”\nCustomer: “All right. I confirm Thursday at three.”'],
  ['interact','Arrange a fictional appointment with a partner. Give one unavailable time, ask for another, and confirm the final details.','Martedì lavoro. Potrebbe spostare la visita a giovedì? Giovedì alle quindici va bene.',['Make the request specific.','Use Lei consistently with a clerk.','Confirm the accepted day and time.'],'Offer one alternative before accepting.'],['v:potere','v:confermare']),
 L('v2-a2-service-cancel','Cancel and explain briefly','I can report a completed booking and cancel it with a short practical explanation.',['v2-a2-service-appointment','v2-a2-past-regular','v2-a2-link-reason-sequence'],['appointments','messages','repair'],[W('prenotare','to book'),W('prenotato','booked (participle)'),W('annullare','to cancel'),W('per un imprevisto','because of an unforeseen problem'),W('numero di prenotazione','booking number'),W('purtroppo','unfortunately')],[
  F('booking','Identify a completed booking',past+' Prenotare → prenotato: ho prenotato is a completed booking, while vorrei prenotare is a request to make one.','Ho prenotato una camera per sabato.','I booked a room for Saturday.',[
   C('Ieri ___ prenotato una camera.','Yesterday I booked a room.','ho',['ho','hai','hanno'],'Io requires ho before prenotato.'),T('Noi ___ prenotato due posti.','We booked two places.','abbiamo','Noi requires abbiamo.'),C('«Avete già una prenotazione?» «___»','Your booking was made yesterday.','Sì, abbiamo prenotato ieri.',['Sì, abbiamo prenotato ieri.','Vorremmo prenotare domani.','Possiamo prenotare?'],'A completed booking answers the question about an existing reservation.'),T('Anna ___ prenotato una visita.','Anna booked a visit.','ha','Anna is third-person singular.'),C('I clienti ___ prenotato per venerdì.','The customers booked for Friday.','hanno',['hanno','ha','abbiamo'],'I clienti is plural and takes hanno.'),T('Tu ___ prenotato un tavolo.','You booked a table.','hai','Tu requires hai.'),T('Voi ___ prenotato il viaggio.','You all booked the trip.','avete','Voi requires avete.')]),
  F('cancel','State the change and a short reason','Vorrei annullare… requests cancellation. Purtroppo softens bad news; perché gives a reason. A number identifies the booking, but never include private account details in a public message.','Purtroppo non posso venire. Vorrei annullare la prenotazione.','Unfortunately I cannot come. I would like to cancel the booking.',[
   C('Non puoi venire. «Vorrei ___ la visita.»','Request cancellation rather than a new booking.','annullare',['annullare','prenotare','confermare'],'Annullare cancels the appointment.'),T('Vorrei ___ la prenotazione di sabato.','I would like to cancel Saturday’s booking.','annullare','Use the infinitive after vorrei.'),C('«Perché annulla?» «___»','Give the supplied unforeseen problem as the reason.','Per un imprevisto.',['Per un imprevisto.','Alle quindici.','Ho prenotato ieri.'],'The reason answers perché; time and booking history answer other questions.'),T('Non posso venire ___ lavoro.','I cannot come because I am working.','perché','Perché links the inability to its reason.'),C('Vuoi solo un’altra data. «___»','You want to keep the visit but change its day.','Vorrei spostare la visita.',['Vorrei spostare la visita.','Vorrei annullare tutto.','Vorrei confermare oggi.'],'Spostare keeps the appointment and changes its date; annullare cancels it.'),T('___, non posso venire domani.','Unfortunately, I cannot come tomorrow. Use the taught softener.','Purtroppo','Purtroppo signals the unwelcome change.'),T('Vorrei annullare ___ non posso partire.','I would like to cancel because I cannot leave.','perché','Perché introduces the stated reason.')])],
  ['read','A brief cancellation','Buongiorno, ho prenotato un tavolo per sabato. Purtroppo non posso venire per un imprevisto. Vorrei annullare la prenotazione. Grazie.','Hello, I booked a table for Saturday. Unfortunately I cannot come because of an unforeseen problem. I would like to cancel the booking. Thank you.'],['write','Write a fictional cancellation with the existing booking, the requested change and one short reason.','Ho prenotato una camera per venerdì. Purtroppo non posso partire. Vorrei annullare la prenotazione.',['Identify the existing booking.','Distinguish cancellation from rescheduling.','Give a concise reason.']],['v:prenotare','v:annullare']),
 L('v2-a2-travel-booking','Choose a travel booking','I can ask about a journey and select an option that meets a stated constraint.',['v2-a2-conditional-request','v2-a2-compare-more-less','v2-a1-opening-times'],['travel','comparison','prices'],[W('andata','outward journey','l’','andate'),W('ritorno','return journey','il','ritorni'),W('diretto','direct'),W('cambio','change/connection','il','cambi'),W('durata','duration','la','durate'),W('partenza','departure','la','partenze'),W('arrivo','arrival','l’','arrivi'),W('andata e ritorno','return ticket/trip')],[
  F('ask','Ask for the information you need','A che ora parte…? asks for departure; a che ora arriva…? asks for arrival. Quanto dura…? asks duration. Partire present: parto, parti, parte, partiamo, partite, partono; arrivare: arrivo, arrivi, arriva, arriviamo, arrivate, arrivano; durare: duro, duri, dura, duriamo, durate, durano. Persons in each row: io, tu, lui/lei/Lei, noi, voi, loro.','A che ora parte il treno? Quanto dura il viaggio?','What time does the train leave? How long does the journey take?',[
   C('Vuoi sapere la partenza. «___»','Ask the departure time.','A che ora parte il treno?',['A che ora parte il treno?','Quanto costa il treno?','Dove arriva il treno?'],'Parte asks when the train departs.'),T('A che ora ___ il treno a Roma?','What time does the train arrive in Rome? Use arrivare in the present.','arriva','Il treno is third-person singular; arriva gives arrival.'),C('«___ dura il viaggio?»','Ask how long the journey takes.','Quanto',['Quanto','Dove','Chi'],'Quanto asks duration here.'),T('A che ora ___ l’autobus?','What time does the bus leave? Use partire in the present.','parte','L’autobus takes parte.'),C('Vuoi anche tornare. «___»','Request a ticket covering both journeys.','Vorrei un biglietto di andata e ritorno.',['Vorrei un biglietto di andata e ritorno.','Vorrei solo l’andata.','Vorrei sapere il binario.'],'Andata e ritorno includes the return.'),T('Quanto ___ il viaggio?','How long does the journey take? Use durare in the present.','dura','Il viaggio takes dura.'),T('Noi ___ alle otto.','We leave at eight. Use partire in the present.','partiamo','Noi takes partiamo.')]),
  F('select','Keep the constraint in the comparison','Più… di and meno… di compare two options. A faster journey may cost more; choose from the supplied constraint rather than assuming one option is best. Diretto means no change on this journey.','Il treno diretto è più veloce, ma costa di più.','The direct train is faster, but costs more.',[
   C('A: venti euro, un cambio. B: trenta euro, diretto. «___»','Your limit is twenty euros. Choose the affordable option.','Scelgo A.',['Scelgo A.','Scelgo B.','Sono uguali.'],'Only A meets the stated budget; no general recommendation is being made.'),T('A dura due ore; B dura tre ore. A è ___ veloce di B.','A takes two hours; B takes three. A is faster than B.','più','Più veloce expresses the shorter journey.'),C('Vuoi evitare un cambio. «___»','Select a direct journey.','Vorrei il treno diretto.',['Vorrei il treno diretto.','Vorrei il treno con un cambio.','Vorrei solo il ritorno.'],'Diretto matches the supplied no-change constraint.'),T('A costa dieci euro; B costa quindici. A costa ___ di B.','A costs ten; B fifteen. A costs less than B.','meno','Meno compares the prices.'),C('A arriva alle nove. B arriva alle dieci. Devi arrivare prima delle dieci.','You must arrive before ten.','Scelgo A.',['Scelgo A.','Scelgo B.','Entrambi arrivano prima delle dieci.'],'At ten is not before ten; only A satisfies the constraint.'),T('B è più comodo ___ A.','B is more comfortable than A. Use the comparison preposition.','di','Use più + adjective + di for these two options.'),T('Il viaggio diretto è ___ lungo di quello con un cambio.','The direct journey is less long than the one with a change.','meno','Meno marks the explicitly supplied lesser duration.')])],['read','Choosing with a limit','Cliente: «Vorrei arrivare prima delle dieci.»\nAddetta: «Il diretto arriva alle nove, ma costa trenta euro. L’altro arriva alle dieci.»\nCliente: «Allora scelgo il diretto.»','Customer: “I would like to arrive before ten.”\nClerk: “The direct train arrives at nine, but costs thirty euros. The other arrives at ten.”\nCustomer: “Then I choose the direct one.”'],['interact','Compare two fictional journey options with a partner. State one constraint, ask a question, and explain your choice.','Vorrei arrivare prima delle dieci. Quanto dura il viaggio diretto? Scelgo il diretto perché arriva alle nove.',['Separate arrival from departure.','State the supplied price/time constraint.','Explain why the chosen option meets it.'],'Offer two options with different price and arrival time.'],['v:partire','v:arrivare','v:durare']),
 L('v2-a2-travel-problem','Explain a travel problem','I can report a travel problem, describe what was happening and request practical help.',['v2-a2-travel-booking','v2-a2-story-contrast','v2-a2-past-irregular'],['travel','past-account','help'],[W('in ritardo','late/delayed'),W('coincidenza','connection','la','coincidenze'),W('perdere una coincidenza','to miss a connection'),W('rimborso','refund','il','rimborsi'),W('biglietteria','ticket office','la','biglietterie'),W('aspettavo','I was waiting'),W('perso','lost/missed (participle)')],[
  F('account','Separate the background from the event','An imperfect describes the scene or ongoing wait; a completed passato prossimo reports what changed. Perdere → perso with avere. Aspettare imperfect: aspettavo, aspettavi, aspettava, aspettavamo, aspettavate, aspettavano (io, tu, lui/lei/Lei, noi, voi, loro).','Aspettavo l’autobus quando ho perso la coincidenza.','I was waiting for the bus when I missed the connection.',[
   C('Il treno ___ in ritardo; poi è arrivato.','The train was late; then it arrived. Describe the background state.','era',['era','sarà','sarebbe'],'Era sets the past background; è arrivato is the later event.'),T('___ l’autobus quando Anna ha chiamato.','I was waiting for the bus when Anna called. Use aspettare in the io imperfect.','Aspettavo','Aspettavo describes the wait underway.'),C('Ho ___ la coincidenza.','I missed the connection. Use the supplied participle of perdere.','perso',['perso','perdevo','perdere'],'Ho needs the participle perso.'),T('Noi ___ perso il treno.','We missed the train.','abbiamo','The completed action uses noi abbiamo + perso.'),C('Prima ___ alla fermata; poi è arrivato il taxi.','First I was at the stop; then the taxi arrived.','ero',['ero','sarò','sono stata domani'],'Ero gives the earlier state rather than a future event.'),T('Loro ___ il treno quando è arrivato un messaggio.','They were waiting for the train when a message arrived. Use the imperfect of aspettare.','aspettavano','Loro takes aspettavano.'),T('Tu ___ perso l’autobus.','You missed the bus.','hai','Tu takes hai before perso.')]),
  F('help','Request a remedy rather than inventing one',request+' Posso cambiare il biglietto? asks permission to change it; dove si trova la biglietteria? requests the place to ask. A refund request does not assert entitlement or a provider’s rules.','Ho perso la coincidenza. Posso cambiare il biglietto?','I missed the connection. Can I change the ticket?',[
   C('Vuoi usare un altro treno. «___»','Ask whether you can change the ticket.','Posso cambiare il biglietto?',['Posso cambiare il biglietto?','Il biglietto è gratuito.','Il rimborso è certo.'],'The question requests an option without inventing a rule.'),T('Potrebbe ___ l’orario del prossimo treno?','Could you confirm the next train’s time?','confermare','Keep the infinitive after potrebbe.'),C('Vuoi sapere dove chiedere aiuto. «___»','Ask for the ticket office location.','Dove si trova la biglietteria?',['Dove si trova la biglietteria?','Quanto dura la biglietteria?','Chi parte la biglietteria?'],'Dove asks for a place.'),T('Posso ___ il biglietto?','Can I change the ticket? Use cambiare.','cambiare','After posso use the infinitive cambiare.'),C('«Il treno è stato cancellato.» «___»','Ask about a refund without asserting a policy.','Posso chiedere un rimborso?',['Posso chiedere un rimborso?','Riceverò sicuramente un rimborso.','Non serve una prenotazione.'],'Ask what is possible; the notice did not state refund terms.'),T('___ aiutarmi, per favore?','Could you help me, please? Use Lei and potere in the conditional.','Potrebbe','Formal Lei uses potrebbe; aiutarmi is the taught infinitive chunk.'),T('Dove si trova la ___?','Where is the ticket office? Use the taught noun.','biglietteria','Biglietteria names the service point.')])],['read','A missed connection','Il primo treno era in ritardo. Ho perso la coincidenza. Sono alla biglietteria: vorrei sapere se posso cambiare il biglietto.','The first train was delayed. I missed the connection. I am at the ticket office: I would like to know whether I can change the ticket.'],['speak','Explain a fictional missed journey and ask one practical question.','Il treno era in ritardo e ho perso la coincidenza. Potrebbe aiutarmi? Posso cambiare il biglietto?',['Give the background and completed problem.','Request a specific next step.','Do not invent a service policy.']],['v:perdere','v:aspettare']),
 L('v2-a2-shopping-exchange','Ask for a replacement','I can identify a purchase problem and request a replacement or information about a refund.',['v2-a2-past-regular','v2-a2-direct-singular','v2-a1-clothes-shop'],['shopping','service-repair','pronoun-reference'],[W('scontrino','receipt','lo','scontrini'),W('difetto','fault','il','difetti'),W('funzionare','to work/function'),W('sostituire','to replace'),W('taglia','size','la','taglie'),W('rimborso','refund','il','rimborsi'),W('comprato','bought (participle)')],[
  F('identify','Identify the item and the fault','Name the item first, then use lo for a masculine singular object or la for feminine singular. Funzionare present: funziono, funzioni, funziona, funzioniamo, funzionate, funzionano (io, tu, lui/lei/Lei, noi, voi, loro). Non funziona describes the fault without guessing its cause.','Ho comprato questo telefono ieri, ma non funziona. Lo vorrei sostituire.','I bought this phone yesterday, but it does not work. I would like to replace it.',[
   C('La giacca è piccola. ___ vorrei cambiare.','Replace la giacca with the object pronoun.','La',['La','Lo','Li'],'La giacca is feminine singular, so la refers back to it.'),T('Il telefono non funziona. ___ vorrei sostituire.','The phone does not work. I would like to replace it. Use the object pronoun.','Lo','Il telefono is masculine singular.'),C('Ho comprato la lampada ieri, ma ___.','State only that the lamp does not work.','non funziona',['non funziona','è rotta perché è vecchia','funzionerà sicuramente'],'Non funziona gives the observed fault without an invented cause or prediction.'),T('Ho ___ la giacca ieri.','I bought the jacket yesterday. Use the participle of comprare.','comprato','Comprare has the regular participle comprato.'),C('Il caricatore è difettoso. «___»','Ask about replacing that masculine singular item.','Lo posso sostituire?',['Lo posso sostituire?','La posso sostituire?','Le posso sostituire?'],'Lo matches il caricatore.'),T('La lampada non ___.','The lamp does not work. Use funzionare in the present.','funziona','The singular lamp takes funziona.'),T('La borsa ha un difetto. ___ vorrei cambiare.','The bag has a fault. I would like to exchange it. Use its object pronoun.','La','La borsa takes la.')]),
  F('remedy','Ask about the available remedy','Vorrei sostituire… requests a replacement; posso avere un rimborso? asks about returning the money. Ho lo scontrino means I have the receipt. These phrases request help; they do not state consumer-law rules.','Ho lo scontrino. Posso avere un rimborso?','I have the receipt. Can I get a refund?',[
   C('Vuoi lo stesso articolo senza difetto. «___»','Request a replacement.','Vorrei sostituire questo articolo.',['Vorrei sostituire questo articolo.','Vorrei comprare due articoli.','Vorrei sapere la partenza.'],'Sostituire means replace the item.'),T('Ho lo ___.','I have the receipt.','scontrino','Lo scontrino is the purchase receipt.'),C('Vuoi chiedere se puoi riavere i soldi. «___»','Ask about a refund.','Posso avere un rimborso?',['Posso avere un rimborso?','Il rimborso è obbligatorio oggi.','Posso provare una taglia?'],'The question asks for the available remedy without inventing entitlement.'),T('Vorrei ___ questa lampada.','I would like to replace this lamp. Use sostituire.','sostituire','Keep the infinitive after vorrei.'),C('La giacca è troppo piccola, ma non ha difetti. «___»','Ask for a larger size.','Posso cambiarla con una taglia più grande?',['Posso cambiarla con una taglia più grande?','Il telefono non funziona.','Ho perso la coincidenza.'],'The request addresses the actual size problem.'),T('Posso avere un ___?','Can I get a refund? Use the taught noun.','rimborso','Rimborso names the money-return request.'),T('Potrebbe ___ questo articolo?','Could you replace this item? Use sostituire.','sostituire','A polite request keeps sostituire in the infinitive.')])],['read','A faulty purchase','Buongiorno, ho comprato questa lampada ieri, ma non funziona. Ho lo scontrino. La posso sostituire?','Hello, I bought this lamp yesterday, but it does not work. I have the receipt. Can I replace it?'],['interact','Describe a fictional purchase fault and ask the shop about one remedy.','Ho comprato questo telefono ieri. Non funziona. Ho lo scontrino: lo posso sostituire?',['Identify the item and observed fault.','Keep lo/la tied to the named item.','Ask about a remedy without claiming a rule.'],'Ask which item and what problem the customer observed.'],['v:funzionare','v:sostituire']),
 L('v2-a2-food-needs','Explain a food requirement','I can state a food restriction, ask about an ingredient and keep a request distinct from an assumption.',['v2-a1-food-preference','v2-a2-conditional-request','v2-a2-nobody-nothing'],['food','service-requests','clarification'],[W('ingrediente','ingredient','l’','ingredienti'),W('latte','milk','il'),W('noci','walnuts'),W('contiene','contains (third-person singular of contenere)'),W('contengono','contain (third-person plural of contenere)'),W('senza','without'),W('sono allergico alle noci','I am allergic to walnuts (male speaker)'),W('sono allergica alle noci','I am allergic to walnuts (female speaker)'),W('non so','I do not know')],[
  F('state','State a requirement clearly','Non mangio… states a food restriction, which may have different reasons. Sono allergico/allergica alle noci states the supplied walnut allergy: choose the ending for the speaker. Asking staff about ingredients does not establish safety when they cannot confirm.','Sono allergica alle noci. Questo dolce contiene noci?','I am allergic to walnuts. Does this dessert contain walnuts?',[
   C('Anna dice: «Sono ___ alle noci.»','Anna states a walnut allergy.','allergica',['allergica','allergico','allergici'],'The feminine singular speaker uses allergica.'),T('Paolo dice: «Sono ___ alle noci.»','Paolo states a walnut allergy.','allergico','The masculine singular speaker uses allergico.'),C('Non mangi carne, ma il motivo non è dato. «___»','State only the supplied restriction.','Non mangio carne.',['Non mangio carne.','Sono allergico a tutto.','La carne non è sicura.'],'Non mangio carne preserves the fact without inventing a medical reason.'),T('Vorrei un piatto ___ carne.','I would like a dish without meat.','senza','Senza introduces the excluded ingredient.'),C('«Questo dolce contiene noci?» «Non so.»','The staff member cannot confirm. What information is established?','The ingredient is unconfirmed.',['The ingredient is unconfirmed.','The dessert has no walnuts.','The dessert is safe for an allergy.'],'Non so means the answer is unknown, not a negative ingredient claim.'),T('Non ___ pesce.','I do not eat fish. Use mangiare in the io present.','mangio','Io uses mangio; the phrase states the restriction only.'),T('Vorrei una bevanda ___ latte.','I would like a drink without milk.','senza','Senza keeps the requested exclusion clear.')]),
  F('check','Ask and confirm rather than assume','For these ingredient questions, the taught chunks are contiene (one dish) and contengono (several dishes). The full irregular contenere paradigm is not assessed here. Può controllare? requests a check; a reply of non so leaves the ingredient unknown.','Questi biscotti contengono latte? Può controllare, per favore?','Do these biscuits contain milk? Can you check, please?',[
   C('Questo piatto ___ latte?','Ask whether one dish contains milk. Use the taught chunk.','contiene',['contiene','contengono','contengo'],'This singular dish uses contiene.'),T('Questi biscotti ___ noci?','Do these biscuits contain walnuts? Use the taught plural chunk.','contengono','Questi biscotti is plural.'),C('L’addetta non sa gli ingredienti. «___»','Request a check.','Può controllare, per favore?',['Può controllare, per favore?','Allora non contiene noci.','Allora è sicuramente adatto.'],'Request verification instead of turning uncertainty into a claim.'),T('Questo dolce ___ latte?','Does this dessert contain milk? Use the taught singular chunk.','contiene','Questo dolce is singular.'),C('«Contiene latte?» «Sì.»','What was confirmed?','The dish contains milk.',['The dish contains milk.','The dish contains no milk.','The dish contains walnuts.'],'Sì confirms only the ingredient asked about.'),T('Può ___ gli ingredienti?','Can you check the ingredients? Use controllare.','controllare','After può keep the infinitive controllare.'),T('Questi piatti ___ carne?','Do these dishes contain meat? Use the taught plural chunk.','contengono','Questi piatti is plural.')])],['read','Checking a menu','Cliente: «Non mangio carne. Questo piatto contiene carne?»\nAddetta: «Non so. Controllo gli ingredienti.»\nCliente: «Grazie, aspetto.»','Customer: “I do not eat meat. Does this dish contain meat?”\nStaff member: “I do not know. I’ll check the ingredients.”\nCustomer: “Thank you, I’ll wait.”'],['interact','Practise a fictional food requirement and an ingredient question. If the answer is unknown, ask the staff member to check.','Vorrei un piatto senza carne. Questo piatto contiene carne? Può controllare gli ingredienti?',['State the supplied restriction precisely.','Ask about the named ingredient.','Keep an unknown reply unknown.'],'Give an unknown reply first, then state the ingredient information you have.']),
 L('v2-a2-home-repair','Report a home problem','I can locate a practical fault at home and ask an appropriate person for help.',['v2-a1-home-rooms','v2-a2-conditional-request','v2-a2-da-duration'],['housing','repair','duration'],[W('riscaldamento','heating','il'),W('rubinetto','tap','il','rubinetti'),W('perdere acqua','to leak water'),W('tecnico','technician','il','tecnici'),W('da ieri','since yesterday'),W('stamattina','this morning'),W('riparare','to repair'),W('non funziona','it does not work')],[
  F('problem','Locate the observed problem','Name what does not work and where it is. Da ieri describes a fault continuing now; ieri has been past time without that duration frame. Non funziona reports an observation rather than diagnosing a cause.','Il riscaldamento non funziona da ieri. Il problema è in camera.','The heating has not worked since yesterday. The problem is in the bedroom.',[
   C('Il rubinetto perde acqua ___ ieri.','The tap has been leaking since yesterday.','da',['da','per domani','tra'],'Da marks the start of the continuing problem.'),T('Il riscaldamento non funziona ___ stamattina.','The heating has not worked since this morning.','da','Da introduces the starting time of the current problem.'),C('La lampada non si accende; non sai la causa. «___»','Report only the observed fault.','La lampada non funziona.',['La lampada non funziona.','L’impianto è sicuramente rotto.','Il tecnico ha sbagliato.'],'Non funziona avoids an unsupported diagnosis.'),T('Il problema è ___ cucina.','The problem is in the kitchen. Use the taught room phrase.','in','In cucina is the established room expression.'),C('Il rubinetto perde acqua. «___»','Ask about the tap rather than the heating.','Il problema è il rubinetto.',['Il problema è il rubinetto.','Il problema è il riscaldamento.','Non c’è una prenotazione.'],'Keep the named item tied to the fault.'),T('La lampada non ___.','The lamp does not work. Use funzionare in the present.','funziona','La lampada takes the singular funziona.'),T('Il problema dura ___ lunedì.','The problem has lasted since Monday.','da','Da marks when the continuing situation began.')]),
  F('request','Ask for a specific next step',request+' Potrebbe mandare un tecnico? asks the recipient to arrange help. Quando può venire? asks availability, not a guaranteed repair time.','Potrebbe mandare un tecnico? Quando può venire?','Could you send a technician? When can they come?',[
   C('Scrivi all’addetto con Lei: «___ mandare un tecnico?»','Request help politely.','Potrebbe',['Potrebbe','Potresti','Potreste'],'Lei takes potrebbe.'),T('Potrebbe ___ un tecnico?','Could you send a technician? Use mandare.','mandare','The requested action stays in the infinitive.'),C('Vuoi sapere il giorno della visita. «___»','Ask when the technician can come.','Quando può venire?',['Quando può venire?','Perché sono allergico?','Quanto dura la cucina?'],'Quando asks the available visit time.'),T('Vorrei ___ il rubinetto.','I would like to repair the tap. Use riparare.','riparare','Keep the infinitive after vorrei.'),C('L’addetto offre domani alle nove. «___»','Accept and confirm the supplied slot.','Domani alle nove va bene.',['Domani alle nove va bene.','Oggi alle nove va bene.','Domani alle dieci va bene.'],'Keep the offered day and time unchanged.'),T('___ confermare l’orario?','Could you confirm the time? Use Lei and potere in the conditional.','Potrebbe','Formal Lei uses potrebbe.'),T('Quando può ___ il tecnico?','When can the technician come? Use venire.','venire','After può keep the infinitive venire.')])],['read','A message to the building contact','Buongiorno, il riscaldamento non funziona da ieri. Il problema è in camera. Potrebbe mandare un tecnico? Sono disponibile domani mattina.','Hello, the heating has not worked since yesterday. The problem is in the bedroom. Could you send a technician? I am available tomorrow morning.'],['write','Write a fictional home-fault message: item, place, starting time, desired help and availability.','Il rubinetto in cucina perde acqua da stamattina. Potrebbe mandare un tecnico? Domani alle nove sono disponibile.',['Describe the observed fault and location.','Keep ongoing duration clear.','Give a specific request and available time.']]),
 L('v2-a2-health-history','Describe a symptom history','I can tell a clinician when a supplied symptom began and ask for clarification.',['v2-a1-health-feeling','v2-a1-health-help','v2-a2-da-duration','v2-a2-past-regular'],['health-language','past-account','clarification'],[W('mal di gola','sore throat'),W('tosse','cough','la'),W('da due giorni','for two days up to now'),W('è iniziato','it started'),W('è iniziata','it started (feminine)'),W('istruzioni','instructions'),W('Può spiegare di nuovo?','Can you explain again?'),W('Non ho capito.','I did not understand.')],[
  F('timeline','Distinguish a present duration from its start','Ho… da due giorni states a symptom continuing now. È iniziato/è iniziata states its start: the ending follows the named symptom. These are language models for a supplied history, not diagnostic advice.','Ho mal di gola da due giorni. La tosse è iniziata ieri.','I have had a sore throat for two days. The cough started yesterday.',[
   C('Ho mal di gola ___ due giorni.','The sore throat is still present and started two days ago.','da',['da','tra','domani'],'Da + duration describes a continuing present symptom.'),T('La tosse è ___ ieri.','The cough started yesterday. Use the taught start participle with feminine agreement.','iniziata','La tosse is feminine singular.'),C('Il mal di gola è ___ lunedì.','The sore throat started on Monday.','iniziato',['iniziato','iniziata','inizieranno'],'Il mal di gola is masculine singular.'),T('Ho la tosse ___ stamattina.','I have had a cough since this morning.','da','Da states the start of a current duration.'),C('Ieri avevo mal di testa; oggi no. «___»','State the supplied past-only symptom.','Ieri avevo mal di testa.',['Ieri avevo mal di testa.','Ho mal di testa da ieri.','Avrò mal di testa domani.'],'Avevo states the past condition without claiming it continues now.'),T('La febbre è ___ sabato.','The fever started on Saturday. Use the taught feminine start participle.','iniziata','La febbre takes iniziata.'),T('Ho mal di testa ___ ieri.','I have had a headache since yesterday.','da','Da ieri keeps the symptom continuing now.')]),
  F('clarify','Say what you did not understand','Non ho capito says the explanation was not understood. Può spiegare di nuovo? asks the clinician to explain again; può scrivere le istruzioni? requests written support. Repeating a medical term alone does not show that you understand an instruction.','Non ho capito le istruzioni. Può spiegare di nuovo?','I did not understand the instructions. Can you explain again?',[
   C('Non hai capito la spiegazione. «___»','Ask for another explanation.','Può spiegare di nuovo?',['Può spiegare di nuovo?','Ho capito tutto.','So già cosa fare.'],'The request directly addresses the missing understanding.'),T('Non ho ___ le istruzioni.','I did not understand the instructions. Use the participle of capire.','capito','Ho + capito reports the missed explanation.'),C('Vuoi conservare le istruzioni scritte. «___»','Request written support.','Può scrivere le istruzioni?',['Può scrivere le istruzioni?','Può annullare la tosse?','Le istruzioni sono inutili.'],'Written instructions provide the requested support.'),T('Può spiegare ___?','Can you explain again? Use the taught two-word repeat phrase.','di nuovo','Di nuovo requests repetition.'),C('Hai sentito una parola, ma non il suo significato. «___»','Ask what the word means.','Che cosa significa?',['Che cosa significa?','Qual è il binario?','Confermo giovedì.'],'Ask for meaning rather than pretending to understand.'),T('Può ___ le istruzioni?','Can you write the instructions? Use scrivere.','scrivere','Use the infinitive after può.'),T('Non ho capito. Può ___ di nuovo?','I did not understand. Can you explain again? Use spiegare.','spiegare','Spiegare requests an explanation, beyond merely repeating a sound.')])],['read','A language-focused consultation','Ho mal di gola da due giorni. La tosse è iniziata ieri. Non ho capito le istruzioni: può scriverle e spiegare di nuovo?','I have had a sore throat for two days. The cough started yesterday. I did not understand the instructions: can you write them and explain again?'],['speak','Practise a fictional symptom history and one clarification request. Use only the supplied facts; do not invent treatment.','Ho mal di gola da ieri. La tosse è iniziata stamattina. Può spiegare di nuovo le istruzioni?',['Keep the supplied symptom and duration.','Distinguish current duration from the starting event.','Ask for clarification when meaning is missing.']])
];

